<script>export let form;</script><section class="page form-wrap"><div class="eyebrow">LOST & FOUND</div><h1>Make a report</h1><p class="sub">A clear title, location and photo can make a big difference.</p>{#if form?.error}<div class="error">{form.error}</div>{/if}<form class="form" method="POST" enctype="multipart/form-data"><label>Report type</label><select name="type" required><option value="lost">Lost animal</option><option value="found">Found animal</option></select><label>Animal</label><select name="animal_type" required><option value="dog">Dog</option><option value="cat">Cat</option></select><label>Title</label><input name="title" required maxlength="120" placeholder="e.g. Bruno missing near Baner"/><label>Description</label><textarea name="description" required placeholder="Colour, collar, identifying marks, what happened..."></textarea><label>Location</label><input name="location" required maxlength="160" placeholder="Area / landmark"/><label>Photo</label><input type="file" name="image" accept="image/*"/><button class="btn primary" type="submit">Publish report</button></form></section>
